// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address claimer, address receiver, uint256 amount) public {
        // Bound amount to avoid overflow/revert in internal logic
        vm.assume(amount < 1e30);
        // Ensure receiver is not the zero address (otherwise claim reverts)
        vm.assume(receiver != address(0));

        // Call claim
        (bool success,) = address(c).call(abi.encodeWithSignature("claim(address,uint256)", receiver, amount));

        // If claim succeeded, then calling transferOwnership to transfer ownership to the receiver should not revert with the zero address error
        if (success) {
            // We check that if we were to call transferOwnership(receiver) after claim, it should succeed (in reference) OR fail (in mutant) 
            // but the general rule is: the reference allows any non-zero address, mutant only zero. So after claim to receiver (non-zero), 
            // transferOwnership should not revert with "Ownable: new owner is the zero address" error in reference.
            // Since we cannot call transferOwnership (onlyOwner) without being owner, we instead assert a proxy condition:
            // The claim function should not set any state that causes the next transferOwnership to fail with the zero address error for a non-zero receiver.
            // We use the public getter to simulate: the owner should not be set to something that breaks the invariant.
            // However, a simpler approach: check that if receiver is non-zero, then the condition in transferOwnership (modified) would reject non-zero.
            // The reference's transferOwnership allows non-zero; mutant only zero. So after claim with non-zero receiver, the mutant would revert.
            // We assert that the call succeeded (meaning no unexpected revert).
            // For the mutant, this call would succeed as well (if it doesn't revert earlier), but the difference manifests only on transferOwnership call.
            // Since we cannot call transferOwnership as non-owner, we use vm.prank to simulate owner calling it.
            vm.prank(c.owner());
            (bool transferSuccess,) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", receiver));
            // The reference should always succeed with non-zero receiver.
            assertTrue(transferSuccess, "transferOwnership should not revert with non-zero receiver");
        } else {
            // If claim reverts, the property is trivially satisfied (no change)
            assertTrue(true);
        }
    }
}

