        vm.assume(amount1 > 0 && amount1 <= 1e30);
        vm.assume(amount2 > 0 && amount2 <= 1e30);

        // Simulate a deposit round
        c.depositUsdc(amount1, user1);
        c.depositUsdc(amount2, user2);

        // Execute batch stake and deposit through keeper
