        c.claim(user1, sharesBefore1);

        // User2 claims all his shares
        uint256 sharesBefore2 = c.unclaimedShares(user2);
        c.claim(user2, sharesBefore2);

        // Total shares claimed should not exceed the total shares minted by the vault
        uint256 totalSharesClaimed = sharesBefore1 + sharesBefore2;
        uint256 totalSharesMinted = c.roundDeposits(1).totalShares;
        assertTrue(totalSharesClaimed <= totalSharesMinted);
    }
}

